INSERT INTO "proposed_control" VALUES('history-budget','gateway','all retained histories and active clones','byte','hard','evict history or reject work','Exploration','Never cache authorization; serialized request copies separate.');
INSERT INTO "proposed_control" VALUES('allocator-trim','native allocator','free retained pages','byte','soft','trim','Exploration','Linux-specific; CPU, contention and next-request faults.');
INSERT INTO "proposed_control" VALUES('replay-disk','broker','permanent exact replay index and WAL','byte','hard','fail closed','Exploration','Exactness, watermark recovery, latency/I/O; no TTL.');
INSERT INTO "proposed_control" VALUES('overlay-budget','storage-host','all native overlays','byte','hard','reject or reviewed spill','Exploration','Disk quota, crash consistency and namespace isolation.');
INSERT INTO "proposed_control" VALUES('queue-budget','gateway/telemetry','per queue count/bytes/age/inflight','byte','hard','reject replies; drop telemetry only','Exploration','Busy replies outside session permits; audit never lossy.');
