-- Sanitized analysis-only relational snapshot. No executor identity or raw contents.
BEGIN TRANSACTION;
CREATE TABLE artifact(id TEXT PRIMARY KEY, attempt_id TEXT REFERENCES attempt, kind TEXT NOT NULL, relative_path TEXT NOT NULL UNIQUE CHECK(relative_path NOT LIKE '/%' AND relative_path NOT LIKE '%..%'), sha256 TEXT NOT NULL CHECK(length(sha256)=64), bytes INTEGER NOT NULL CHECK(bytes>=0), privacy TEXT NOT NULL CHECK(privacy IN ('private','sanitized')), created_at TEXT NOT NULL);
CREATE TABLE assignment(experiment_id TEXT REFERENCES experiment, factor_id TEXT NOT NULL, level_id TEXT NOT NULL, PRIMARY KEY(experiment_id,factor_id), FOREIGN KEY(factor_id,level_id) REFERENCES factor_level(factor_id,id));
CREATE TABLE attempt(id TEXT PRIMARY KEY, trial_id TEXT NOT NULL REFERENCES trial, number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 2), previous_id TEXT REFERENCES attempt, status TEXT NOT NULL CHECK(status IN ('claimed','running','blocked','interrupted','failed','succeeded','attention')), started_at TEXT NOT NULL, ended_at TEXT, environment_id TEXT REFERENCES environment, driver_sha256 TEXT NOT NULL CHECK(length(driver_sha256)=64), condition_sha256 TEXT NOT NULL CHECK(length(condition_sha256)=64), command_json TEXT NOT NULL CHECK(json_valid(command_json)), parser_id TEXT NOT NULL, exit_code INTEGER, signal INTEGER, cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK(cancel_requested IN (0,1)), free_before_bytes INTEGER CHECK(free_before_bytes>=0), free_after_bytes INTEGER CHECK(free_after_bytes>=0), UNIQUE(trial_id,number), CHECK((number=1 AND previous_id IS NULL) OR (number=2 AND previous_id IS NOT NULL)));
CREATE TABLE attempt_input(attempt_id TEXT NOT NULL REFERENCES attempt, role TEXT NOT NULL REFERENCES binary_version, artifact_id TEXT NOT NULL REFERENCES binary_product, PRIMARY KEY(attempt_id,role));
CREATE TABLE attempt_outcome(attempt_id TEXT PRIMARY KEY NOT NULL REFERENCES attempt, status TEXT NOT NULL CHECK(status IN ('failed','blocked','interrupted','succeeded')), exit_code INTEGER, error_id INTEGER REFERENCES error, recorded_at TEXT NOT NULL);
CREATE TABLE binary_product(artifact_id TEXT PRIMARY KEY NOT NULL, producer_attempt_id TEXT NOT NULL REFERENCES attempt, role TEXT NOT NULL REFERENCES binary_version, build_id TEXT NOT NULL REFERENCES build, source_id TEXT REFERENCES source_revision, input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64), source_artifact_id TEXT NOT NULL, build_log_artifact_id TEXT NOT NULL,
 FOREIGN KEY(artifact_id,producer_attempt_id) REFERENCES artifact(id,attempt_id),
 FOREIGN KEY(source_artifact_id,producer_attempt_id) REFERENCES artifact(id,attempt_id),
 FOREIGN KEY(build_log_artifact_id,producer_attempt_id) REFERENCES artifact(id,attempt_id));
CREATE TABLE binary_requirement(consumer_build_id TEXT NOT NULL REFERENCES build, role TEXT NOT NULL REFERENCES binary_version, producer_build_id TEXT NOT NULL REFERENCES build, source_id TEXT REFERENCES source_revision, PRIMARY KEY(consumer_build_id,role));
CREATE TABLE binary_version(role TEXT PRIMARY KEY NOT NULL CHECK(role IN ('collector','history')), input_sha256 TEXT NOT NULL CHECK(length(input_sha256)=64));
CREATE TABLE build(id TEXT PRIMARY KEY, source_id TEXT REFERENCES source_revision, image TEXT NOT NULL, compiler TEXT, flags TEXT NOT NULL, allocator TEXT NOT NULL, binary_sha256 TEXT CHECK(binary_sha256 IS NULL OR length(binary_sha256)=64), symbols_sha256 TEXT CHECK(symbols_sha256 IS NULL OR length(symbols_sha256)=64));
CREATE TABLE campaign(id TEXT PRIMARY KEY, created_at TEXT NOT NULL, seed INTEGER NOT NULL, driver_sha256 TEXT NOT NULL CHECK(length(driver_sha256)=64), status TEXT NOT NULL CHECK(status IN ('open','closed')));
CREATE TABLE cleanup(id INTEGER PRIMARY KEY, attempt_id TEXT REFERENCES attempt, target TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('refused','retained','removed','drained')), reason TEXT NOT NULL, free_before_bytes INTEGER, free_after_bytes INTEGER, at TEXT NOT NULL);
CREATE TABLE comparison_group(id TEXT PRIMARY KEY, question TEXT NOT NULL, required_replicates INTEGER NOT NULL DEFAULT 3 CHECK(required_replicates>=3));
CREATE TABLE comparison_member(group_id TEXT REFERENCES comparison_group, experiment_id TEXT REFERENCES experiment, role TEXT NOT NULL CHECK(role IN ('baseline','control','variant')), PRIMARY KEY(group_id,experiment_id));
CREATE TABLE environment(id TEXT PRIMARY KEY, os TEXT NOT NULL, architecture TEXT NOT NULL, page_bytes INTEGER CHECK(page_bytes>0), libc TEXT, daemon_id TEXT NOT NULL, limits_json TEXT NOT NULL CHECK(json_valid(limits_json)), load_json TEXT NOT NULL CHECK(json_valid(load_json)), filesystem TEXT, tool_versions_json TEXT NOT NULL CHECK(json_valid(tool_versions_json)));
CREATE TABLE error(id INTEGER PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempt, category TEXT NOT NULL CHECK(category IN ('transient','missing-dependency','unsafe-prerequisite','resource-exhaustion','fixture-parser','benchmark','interrupted','ownership')), message TEXT NOT NULL, retryable INTEGER NOT NULL CHECK(retryable IN (0,1)), at TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'primary' CHECK(role IN ('primary','cleanup')));
CREATE TABLE execution_sequence(sequence INTEGER PRIMARY KEY AUTOINCREMENT, attempt_id TEXT NOT NULL UNIQUE REFERENCES attempt, claimed_at TEXT NOT NULL, launch_sequence INTEGER UNIQUE, dispatched_at TEXT, start_observed_at TEXT);
CREATE TABLE executor_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1), uuid TEXT NOT NULL, driver_sha256 TEXT NOT NULL, db_device INTEGER NOT NULL, db_inode INTEGER NOT NULL);
CREATE TABLE experiment(id TEXT PRIMARY KEY, study_id TEXT NOT NULL REFERENCES study, hypothesis_id TEXT REFERENCES hypothesis, lane TEXT NOT NULL CHECK(lane IN ('runtime','state','infra')), stage INTEGER NOT NULL CHECK(stage BETWEEN 0 AND 3), priority INTEGER NOT NULL CHECK(priority>=0), recipe_id TEXT NOT NULL REFERENCES recipe, build_id TEXT REFERENCES build, provider_set_id TEXT REFERENCES provider_set, status TEXT NOT NULL CHECK(status IN ('planned','ready','unsupported','blocked','skipped')), reason TEXT NOT NULL, config_json TEXT NOT NULL CHECK(json_valid(config_json)));
CREATE TABLE experiment_dependency(experiment_id TEXT REFERENCES experiment, predecessor_id TEXT REFERENCES experiment, PRIMARY KEY(experiment_id,predecessor_id), CHECK(experiment_id!=predecessor_id));
CREATE TABLE experiment_prerequisite(experiment_id TEXT REFERENCES experiment, prerequisite_id TEXT REFERENCES prerequisite, PRIMARY KEY(experiment_id,prerequisite_id));
CREATE TABLE factor(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('integer','real','text','boolean')), unit TEXT NOT NULL);
CREATE TABLE factor_level(factor_id TEXT REFERENCES factor, id TEXT NOT NULL, kind TEXT NOT NULL, integer_value INTEGER, real_value REAL, text_value TEXT, PRIMARY KEY(factor_id,id), CHECK((kind='integer' AND integer_value IS NOT NULL AND real_value IS NULL AND text_value IS NULL) OR (kind='boolean' AND integer_value IS NOT NULL AND integer_value IN (0,1) AND real_value IS NULL AND text_value IS NULL) OR (kind='real' AND real_value IS NOT NULL AND integer_value IS NULL AND text_value IS NULL) OR (kind='text' AND text_value IS NOT NULL AND integer_value IS NULL AND real_value IS NULL)));
CREATE TABLE finding(id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('source-supported','observed','inferred','unknown')), claim TEXT NOT NULL, limitation TEXT NOT NULL);
CREATE TABLE finding_evidence(finding_id TEXT REFERENCES finding, reference_id TEXT REFERENCES reference, artifact_id TEXT REFERENCES artifact, parse_id TEXT REFERENCES parse_run, CHECK((reference_id IS NOT NULL)+(artifact_id IS NOT NULL)+(parse_id IS NOT NULL)=1), UNIQUE(finding_id,reference_id,artifact_id,parse_id));
CREATE TABLE followup(id TEXT PRIMARY KEY, hypothesis_id TEXT REFERENCES hypothesis, question TEXT NOT NULL, expected_gain TEXT NOT NULL, safe_recipe TEXT NOT NULL, bound TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','blocked','done')));
CREATE TABLE followup_dependency(followup_id TEXT REFERENCES followup, experiment_id TEXT REFERENCES experiment, PRIMARY KEY(followup_id,experiment_id));
CREATE TABLE hypothesis(id TEXT PRIMARY KEY, subsystem_id TEXT NOT NULL REFERENCES subsystem, question TEXT NOT NULL, disposition TEXT NOT NULL CHECK(disposition IN ('accepted','deferred','rejected')), limitation TEXT NOT NULL);
CREATE TABLE hypothesis_reference(hypothesis_id TEXT REFERENCES hypothesis, reference_id TEXT REFERENCES reference, PRIMARY KEY(hypothesis_id,reference_id));
CREATE TABLE metric(id TEXT PRIMARY KEY, unit TEXT NOT NULL, definition TEXT NOT NULL, aggregation TEXT NOT NULL CHECK(aggregation IN ('gauge','counter','duration')));
CREATE TABLE missing_metric(attempt_id TEXT REFERENCES attempt, metric_id TEXT REFERENCES metric, reason TEXT NOT NULL, PRIMARY KEY(attempt_id,metric_id));
CREATE TABLE parse_run(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempt, parser_sha256 TEXT NOT NULL CHECK(length(parser_sha256)=64), input_artifact_id TEXT NOT NULL REFERENCES artifact, at TEXT NOT NULL, supersedes TEXT REFERENCES parse_run);
CREATE TABLE parse_scope(parse_id TEXT PRIMARY KEY NOT NULL REFERENCES parse_run, memory_scope TEXT NOT NULL CHECK(memory_scope IN ('whole-run-only','history-synchronized','recipe-phases')), protocol TEXT NOT NULL);
CREATE TABLE phase_summary(parse_id TEXT REFERENCES parse_run, phase TEXT NOT NULL, metric_id TEXT REFERENCES metric, n INTEGER NOT NULL CHECK(n>0), minimum REAL NOT NULL, maximum REAL NOT NULL, mean REAL NOT NULL, p50 REAL NOT NULL, p95 REAL NOT NULL, PRIMARY KEY(parse_id,phase,metric_id));
CREATE TABLE prerequisite(id TEXT PRIMARY KEY, description TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('implemented','artifact','trial','manual')));
CREATE TABLE prerequisite_evidence(prerequisite_id TEXT PRIMARY KEY NOT NULL REFERENCES prerequisite, satisfied INTEGER NOT NULL CHECK(satisfied IN (0,1)), evidence TEXT NOT NULL REFERENCES artifact, updated_at TEXT NOT NULL);
CREATE TABLE proposed_control(id TEXT PRIMARY KEY, owner TEXT NOT NULL, scope TEXT NOT NULL, unit TEXT NOT NULL, ceiling TEXT NOT NULL CHECK(ceiling IN ('hard','soft')), pressure_response TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Current','Committed direction','Exploration')), tradeoff TEXT NOT NULL);
CREATE TABLE provider(id TEXT PRIMARY KEY, sha256 TEXT CHECK(sha256 IS NULL OR length(sha256)=64), bytes INTEGER CHECK(bytes>0), manifest_bytes INTEGER CHECK(manifest_bytes>=0));
CREATE TABLE provider_member(set_id TEXT REFERENCES provider_set, ordinal INTEGER CHECK(ordinal>=0), provider_id TEXT REFERENCES provider, PRIMARY KEY(set_id,ordinal), UNIQUE(set_id,provider_id));
CREATE TABLE provider_set(id TEXT PRIMARY KEY, qualification TEXT NOT NULL);
CREATE TABLE recipe(id TEXT PRIMARY KEY, implementation TEXT NOT NULL, classification TEXT NOT NULL CHECK(classification IN ('infra','release-replica','source-kernel','library','prototype','unsupported')), timeout_s INTEGER NOT NULL CHECK(timeout_s BETWEEN 1 AND 180), memory_bytes INTEGER NOT NULL CHECK(memory_bytes BETWEEN 33554432 AND 1073741824), pids INTEGER NOT NULL CHECK(pids BETWEEN 4 AND 128), cpus REAL NOT NULL CHECK(cpus>0 AND cpus<=2), output_bytes INTEGER NOT NULL CHECK(output_bytes BETWEEN 1024 AND 16777216));
CREATE TABLE recovery(id INTEGER PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempt, decision TEXT NOT NULL CHECK(decision IN ('refused','drained','attention')), reason TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE reference(id TEXT PRIMARY KEY, revision TEXT NOT NULL, locator TEXT NOT NULL, qualification TEXT NOT NULL);
CREATE TABLE resource(attempt_id TEXT PRIMARY KEY REFERENCES attempt, token TEXT NOT NULL UNIQUE, daemon_id TEXT NOT NULL, container_name TEXT NOT NULL UNIQUE, container_id TEXT UNIQUE, created_at TEXT, started_at TEXT, volume_name TEXT NOT NULL UNIQUE, drained_at TEXT);
CREATE TABLE sample(parse_id TEXT REFERENCES parse_run, ordinal INTEGER NOT NULL CHECK(ordinal>=0), phase TEXT NOT NULL, elapsed_ns INTEGER NOT NULL CHECK(elapsed_ns>=0), metric_id TEXT NOT NULL REFERENCES metric, value REAL NOT NULL CHECK(value>=0 AND value<1e100), clock_origin TEXT NOT NULL DEFAULT 'legacy-unspecified', PRIMARY KEY(parse_id,ordinal,metric_id));
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, sha256 TEXT NOT NULL CHECK(length(sha256)=64));
CREATE TABLE slot(id INTEGER PRIMARY KEY CHECK(id IN (1,2)), attempt_id TEXT UNIQUE REFERENCES attempt, token TEXT UNIQUE, heartbeat_at TEXT, CHECK((attempt_id IS NULL AND token IS NULL AND heartbeat_at IS NULL) OR (attempt_id IS NOT NULL AND token IS NOT NULL AND heartbeat_at IS NOT NULL)));
CREATE TABLE source_revision(id TEXT PRIMARY KEY, git_sha TEXT NOT NULL CHECK(length(git_sha)=40), lock_sha256 TEXT, version TEXT NOT NULL, qualification TEXT NOT NULL);
CREATE TABLE study(id TEXT PRIMARY KEY, title TEXT NOT NULL, source_digest TEXT NOT NULL);
CREATE TABLE subsystem(id TEXT PRIMARY KEY, lane TEXT NOT NULL CHECK(lane IN ('runtime','state','infra')), owner TEXT NOT NULL);
CREATE TABLE trial(id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaign, experiment_id TEXT NOT NULL REFERENCES experiment, replicate INTEGER NOT NULL CHECK(replicate BETWEEN 1 AND 3), order_index INTEGER NOT NULL CHECK(order_index>=0), pair_id TEXT REFERENCES trial, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','blocked','skipped','interrupted','failed','succeeded')), UNIQUE(campaign_id,experiment_id,replicate), UNIQUE(campaign_id,order_index));
CREATE TABLE trial_incident(id INTEGER PRIMARY KEY, trial_id TEXT NOT NULL REFERENCES trial, stage TEXT NOT NULL, category TEXT NOT NULL, message TEXT NOT NULL, at TEXT NOT NULL);
CREATE VIEW matrix AS SELECT e.id,e.lane,e.stage,e.priority,e.status,e.reason,e.hypothesis_id,r.classification,e.recipe_id,a.factor_id,l.kind,l.integer_value,l.real_value,l.text_value,f.unit FROM experiment e JOIN recipe r ON r.id=e.recipe_id LEFT JOIN assignment a ON a.experiment_id=e.id LEFT JOIN factor_level l ON l.factor_id=a.factor_id AND l.id=a.level_id LEFT JOIN factor f ON f.id=a.factor_id;
CREATE VIEW coverage AS SELECT e.id,e.lane,e.stage,e.status AS cell_status,r.classification,COUNT(t.id) AS trials,SUM(CASE WHEN t.status='succeeded' THEN 1 ELSE 0 END) AS succeeded, e.reason FROM experiment e JOIN recipe r ON r.id=e.recipe_id LEFT JOIN trial t ON t.experiment_id=e.id GROUP BY e.id;
CREATE VIEW latest_parse AS SELECT p.* FROM parse_run p WHERE NOT EXISTS(SELECT 1 FROM parse_run n WHERE n.supersedes=p.id);
CREATE UNIQUE INDEX finding_reference_once ON finding_evidence(finding_id,reference_id) WHERE reference_id IS NOT NULL;
CREATE UNIQUE INDEX finding_artifact_once ON finding_evidence(finding_id,artifact_id) WHERE artifact_id IS NOT NULL;
CREATE UNIQUE INDEX finding_parse_once ON finding_evidence(finding_id,parse_id) WHERE parse_id IS NOT NULL;
CREATE UNIQUE INDEX artifact_owner ON artifact(id,attempt_id);
CREATE VIEW unresolved AS SELECT e.id,e.lane,e.reason,p.id AS prerequisite,p.description,CASE WHEN p.kind='artifact' THEN EXISTS(SELECT 1 FROM binary_requirement r JOIN binary_version v ON v.role=r.role JOIN binary_product b ON b.role=r.role AND b.build_id=r.producer_build_id AND b.source_id IS r.source_id AND b.input_sha256=v.input_sha256 JOIN attempt a ON a.id=b.producer_attempt_id WHERE r.consumer_build_id=e.build_id AND r.role=p.id AND a.status='succeeded') ELSE COALESCE(pe.satisfied,0) END AS satisfied FROM experiment e LEFT JOIN experiment_prerequisite ep ON ep.experiment_id=e.id LEFT JOIN prerequisite p ON p.id=ep.prerequisite_id LEFT JOIN prerequisite_evidence pe ON pe.prerequisite_id=p.id;
CREATE VIEW results AS SELECT t.campaign_id,t.experiment_id,t.replicate,a.id AS attempt_id,a.status,e.architecture,e.page_bytes,COALESCE(scope.memory_scope,'whole-run-only') AS memory_scope,s.*,m.unit FROM phase_summary s JOIN latest_parse p ON p.id=s.parse_id JOIN attempt a ON a.id=p.attempt_id JOIN trial t ON t.id=a.trial_id LEFT JOIN environment e ON e.id=a.environment_id LEFT JOIN parse_scope scope ON scope.parse_id=p.id JOIN metric m ON m.id=s.metric_id;
CREATE TRIGGER compatible_input BEFORE INSERT ON attempt_input WHEN NOT EXISTS(SELECT 1 FROM attempt a JOIN trial t ON t.id=a.trial_id JOIN experiment e ON e.id=t.experiment_id JOIN binary_requirement r ON r.consumer_build_id=e.build_id AND r.role=NEW.role JOIN binary_version v ON v.role=r.role JOIN binary_product p ON p.artifact_id=NEW.artifact_id JOIN attempt producer ON producer.id=p.producer_attempt_id WHERE a.id=NEW.attempt_id AND p.role=r.role AND p.build_id=r.producer_build_id AND p.source_id IS r.source_id AND p.input_sha256=v.input_sha256 AND producer.status='succeeded') BEGIN SELECT RAISE(ABORT,'incompatible binary input'); END;
CREATE TRIGGER fixed_attempt_condition BEFORE UPDATE ON attempt WHEN NEW.trial_id!=OLD.trial_id OR NEW.number!=OLD.number OR NEW.driver_sha256!=OLD.driver_sha256 OR NEW.condition_sha256!=OLD.condition_sha256 OR NEW.command_json!=OLD.command_json BEGIN SELECT RAISE(ABORT,'immutable attempt condition'); END;
CREATE TRIGGER fixed_resource_owner BEFORE UPDATE ON resource WHEN NEW.token!=OLD.token OR NEW.daemon_id!=OLD.daemon_id OR NEW.container_name!=OLD.container_name OR NEW.volume_name!=OLD.volume_name OR (OLD.container_id IS NOT NULL AND NEW.container_id IS NOT OLD.container_id) OR (OLD.created_at IS NOT NULL AND NEW.created_at IS NOT OLD.created_at) OR (OLD.started_at IS NOT NULL AND NEW.started_at IS NOT OLD.started_at) BEGIN SELECT RAISE(ABORT,'immutable process-tree identity'); END;
CREATE TRIGGER immutable_artifact BEFORE UPDATE ON artifact BEGIN SELECT RAISE(ABORT,'immutable evidence'); END;
CREATE TRIGGER immutable_input BEFORE UPDATE ON attempt_input BEGIN SELECT RAISE(ABORT,'immutable input link'); END;
CREATE TRIGGER immutable_outcome BEFORE UPDATE ON attempt_outcome BEGIN SELECT RAISE(ABORT,'retain primary outcome'); END;
CREATE TRIGGER immutable_product BEFORE UPDATE ON binary_product BEGIN SELECT RAISE(ABORT,'immutable binary provenance'); END;
CREATE TRIGGER keep_slots BEFORE DELETE ON slot BEGIN SELECT RAISE(ABORT,'fixed global slots'); END;
CREATE TRIGGER pk_artifact_insert BEFORE INSERT ON artifact WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_artifact_update BEFORE UPDATE ON artifact WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_assignment_insert BEFORE INSERT ON assignment WHEN NEW.experiment_id IS NULL OR NEW.factor_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_assignment_update BEFORE UPDATE ON assignment WHEN NEW.experiment_id IS NULL OR NEW.factor_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_attempt_insert BEFORE INSERT ON attempt WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_attempt_update BEFORE UPDATE ON attempt WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_build_insert BEFORE INSERT ON build WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_build_update BEFORE UPDATE ON build WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_campaign_insert BEFORE INSERT ON campaign WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_campaign_update BEFORE UPDATE ON campaign WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_comparison_group_insert BEFORE INSERT ON comparison_group WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_comparison_group_update BEFORE UPDATE ON comparison_group WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_comparison_member_insert BEFORE INSERT ON comparison_member WHEN NEW.group_id IS NULL OR NEW.experiment_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_comparison_member_update BEFORE UPDATE ON comparison_member WHEN NEW.group_id IS NULL OR NEW.experiment_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_environment_insert BEFORE INSERT ON environment WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_environment_update BEFORE UPDATE ON environment WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_experiment_dependency_insert BEFORE INSERT ON experiment_dependency WHEN NEW.experiment_id IS NULL OR NEW.predecessor_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_experiment_dependency_update BEFORE UPDATE ON experiment_dependency WHEN NEW.experiment_id IS NULL OR NEW.predecessor_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_experiment_insert BEFORE INSERT ON experiment WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_experiment_prerequisite_insert BEFORE INSERT ON experiment_prerequisite WHEN NEW.experiment_id IS NULL OR NEW.prerequisite_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_experiment_prerequisite_update BEFORE UPDATE ON experiment_prerequisite WHEN NEW.experiment_id IS NULL OR NEW.prerequisite_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_experiment_update BEFORE UPDATE ON experiment WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_factor_insert BEFORE INSERT ON factor WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_factor_level_insert BEFORE INSERT ON factor_level WHEN NEW.factor_id IS NULL OR NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_factor_level_update BEFORE UPDATE ON factor_level WHEN NEW.factor_id IS NULL OR NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_factor_update BEFORE UPDATE ON factor WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_finding_insert BEFORE INSERT ON finding WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_finding_update BEFORE UPDATE ON finding WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_followup_dependency_insert BEFORE INSERT ON followup_dependency WHEN NEW.followup_id IS NULL OR NEW.experiment_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_followup_dependency_update BEFORE UPDATE ON followup_dependency WHEN NEW.followup_id IS NULL OR NEW.experiment_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_followup_insert BEFORE INSERT ON followup WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_followup_update BEFORE UPDATE ON followup WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_hypothesis_insert BEFORE INSERT ON hypothesis WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_hypothesis_reference_insert BEFORE INSERT ON hypothesis_reference WHEN NEW.hypothesis_id IS NULL OR NEW.reference_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_hypothesis_reference_update BEFORE UPDATE ON hypothesis_reference WHEN NEW.hypothesis_id IS NULL OR NEW.reference_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_hypothesis_update BEFORE UPDATE ON hypothesis WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_metric_insert BEFORE INSERT ON metric WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_metric_update BEFORE UPDATE ON metric WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_missing_metric_insert BEFORE INSERT ON missing_metric WHEN NEW.attempt_id IS NULL OR NEW.metric_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_missing_metric_update BEFORE UPDATE ON missing_metric WHEN NEW.attempt_id IS NULL OR NEW.metric_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_parse_run_insert BEFORE INSERT ON parse_run WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_parse_run_update BEFORE UPDATE ON parse_run WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_phase_summary_insert BEFORE INSERT ON phase_summary WHEN NEW.parse_id IS NULL OR NEW.phase IS NULL OR NEW.metric_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_phase_summary_update BEFORE UPDATE ON phase_summary WHEN NEW.parse_id IS NULL OR NEW.phase IS NULL OR NEW.metric_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_prerequisite_insert BEFORE INSERT ON prerequisite WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_prerequisite_update BEFORE UPDATE ON prerequisite WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_proposed_control_insert BEFORE INSERT ON proposed_control WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_proposed_control_update BEFORE UPDATE ON proposed_control WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_provider_insert BEFORE INSERT ON provider WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_provider_member_insert BEFORE INSERT ON provider_member WHEN NEW.set_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_provider_member_update BEFORE UPDATE ON provider_member WHEN NEW.set_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_provider_set_insert BEFORE INSERT ON provider_set WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_provider_set_update BEFORE UPDATE ON provider_set WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_provider_update BEFORE UPDATE ON provider WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_recipe_insert BEFORE INSERT ON recipe WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_recipe_update BEFORE UPDATE ON recipe WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_reference_insert BEFORE INSERT ON reference WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_reference_update BEFORE UPDATE ON reference WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_resource_insert BEFORE INSERT ON resource WHEN NEW.attempt_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_resource_update BEFORE UPDATE ON resource WHEN NEW.attempt_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_sample_insert BEFORE INSERT ON sample WHEN NEW.parse_id IS NULL OR NEW.metric_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_sample_update BEFORE UPDATE ON sample WHEN NEW.parse_id IS NULL OR NEW.metric_id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_source_revision_insert BEFORE INSERT ON source_revision WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_source_revision_update BEFORE UPDATE ON source_revision WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_study_insert BEFORE INSERT ON study WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_study_update BEFORE UPDATE ON study WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_subsystem_insert BEFORE INSERT ON subsystem WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_subsystem_update BEFORE UPDATE ON subsystem WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_trial_insert BEFORE INSERT ON trial WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_trial_update BEFORE UPDATE ON trial WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER product_producer BEFORE INSERT ON binary_product WHEN NOT EXISTS(SELECT 1 FROM attempt a JOIN trial t ON t.id=a.trial_id JOIN experiment e ON e.id=t.experiment_id JOIN artifact f ON f.id=NEW.artifact_id WHERE a.id=NEW.producer_attempt_id AND e.build_id=NEW.build_id AND e.recipe_id='build-'||NEW.role AND f.kind='binary') BEGIN SELECT RAISE(ABORT,'incompatible binary producer'); END;
CREATE TRIGGER retained_artifact BEFORE DELETE ON artifact BEGIN SELECT RAISE(ABORT,'retain evidence'); END;
CREATE TRIGGER retained_input BEFORE DELETE ON attempt_input BEGIN SELECT RAISE(ABORT,'retain input link'); END;
CREATE TRIGGER retained_product BEFORE DELETE ON binary_product BEGIN SELECT RAISE(ABORT,'retain binary provenance'); END;
CREATE TRIGGER retry_link BEFORE INSERT ON attempt WHEN NEW.number=2 AND NOT EXISTS(SELECT 1 FROM attempt a WHERE a.id=NEW.previous_id AND a.trial_id=NEW.trial_id AND a.number=1 AND a.condition_sha256=NEW.condition_sha256 AND a.driver_sha256=NEW.driver_sha256 AND a.status IN ('failed','interrupted','blocked')) BEGIN SELECT RAISE(ABORT,'retry must preserve condition and predecessor'); END;
CREATE TRIGGER typed_level BEFORE INSERT ON factor_level WHEN NEW.kind != (SELECT kind FROM factor WHERE id=NEW.factor_id) BEGIN SELECT RAISE(ABORT,'factor kind mismatch'); END;
CREATE TRIGGER typed_level_update BEFORE UPDATE ON factor_level WHEN NEW.kind != (SELECT kind FROM factor WHERE id=NEW.factor_id) BEGIN SELECT RAISE(ABORT,'factor kind mismatch'); END;
DELETE FROM "sqlite_sequence";
COMMIT;
PRAGMA user_version = 4;
